/** Canonical assertion encoding: UTF-8 `v1\0`, then fixed fields in this order; each is `name=<decimal byte length>:<UTF-8 value>|`. Lists are sorted and joined with `,`; no whitespace or JSON maps are accepted. */
export function canonicalAssertion(fields: Record<string, string | string[]>): Uint8Array {
  const names = ["client_ref", "client_version", "session_ref", "agent_ref", "directory", "worktree", "requested_product_id", "requested_project_ids", "requested_capabilities", "issued_at", "nonce", "surface_range", "envelope_versions", "manifest_digest"];
  const body = names.map((name) => { const raw = fields[name] ?? ""; const value = Array.isArray(raw) ? [...raw].sort().join(",") : raw; const bytes = new TextEncoder().encode(value); return `${name}=${bytes.length}:${value}|`; }).join("");
  return new TextEncoder().encode(`v1\0${body}`);
}
